using System.ComponentModel.DataAnnotations;
namespace MotoHubAPI.Models;
public class AppUser { public int Id {get;set;} [Required,MaxLength(120)] public string FullName {get;set;}=""; [Required,EmailAddress,MaxLength(180)] public string Email {get;set;}=""; [Required] public string PasswordHash {get;set;}=""; [MaxLength(20)] public string Role {get;set;}="Customer"; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; }
public class Motorcycle { public int Id {get;set;} public int UserId {get;set;} [Required,MaxLength(80)] public string Make {get;set;}=""; [Required,MaxLength(80)] public string Model {get;set;}=""; public int Year {get;set;} [MaxLength(40)] public string PlateNumber {get;set;}=""; public AppUser? User {get;set;} }
public class ServiceItem { public int Id {get;set;} [Required,MaxLength(120)] public string Name {get;set;}=""; [MaxLength(1000)] public string Description {get;set;}=""; public decimal Price {get;set;} public int DurationMinutes {get;set;}=60; public bool IsActive {get;set;}=true; }
public class PartItem { public int Id {get;set;} [Required,MaxLength(120)] public string Name {get;set;}=""; [MaxLength(100)] public string SKU {get;set;}=""; public decimal Price {get;set;} public int Stock {get;set;} public bool IsActive {get;set;}=true; }
public class Booking { public int Id {get;set;} public int UserId {get;set;} public int MotorcycleId {get;set;} public int ServiceItemId {get;set;} public DateTime ScheduledAt {get;set;} public string Status {get;set;}="Pending"; [MaxLength(1000)] public string Notes {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public AppUser? User {get;set;} public Motorcycle? Motorcycle {get;set;} public ServiceItem? ServiceItem {get;set;} }
